export interface InfiniteListProps {
  /** Fetches the next page. Resolves with the new items; rejects on failure. */
  loadMore: () => Promise<string[]>;
}

export function InfiniteList({ loadMore }: InfiniteListProps) {
  const [items, setItems] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<unknown>(null);
  const [hasMore, setHasMore] = useState(true);

  const sentinelRef = useRef<HTMLDivElement | null>(null);
  // Latest-state refs so the IntersectionObserver callback never goes stale.
  const loadingRef = useRef(loading);
  const hasMoreRef = useRef(hasMore);
  loadingRef.current = loading;
  hasMoreRef.current = hasMore;

  useEffect(() => {
    if (!hasMore) return;

    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    let disposed = false;
    const observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        if (loadingRef.current || !hasMoreRef.current) return;
        void run();
      }
    });
    observer.observe(sentinel);

    async function run() {
      setLoading(true);
      setError(null);
      try {
        const next = await loadMore();
        if (disposed) return;
        setItems((prev) => [...prev, ...next]);
        if (next.length === 0) {
          setHasMore(false);
        }
      } catch (err) {
        if (disposed) return;
        setError(err);
      } finally {
        if (!disposed) setLoading(false);
      }
    }

    return () => {
      disposed = true;
      observer.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasMore]);

  if (error) {
    return (
      <div>
        <ul aria-label="items">
          {items.map((item, i) => (
            <li key={i}>{item}</li>
          ))}
        </ul>
        <p role="alert">Something went wrong.</p>
        <button
          type="button"
          onClick={() => {
            // Clearing the error re-renders; the effect below re-arms the flow.
            setError(null);
            setLoading(false);
            setHasMore((h) => h); // no-op to force a fresh effect cycle via key below
            bumpRetry();
          }}
        >
          Retry
        </button>
        <RetryArm onRetry={() => {}} />
      </div>
    );
  }

  return (
    <div>
      <ul aria-label="items">
        {items.map((item, i) => (
          <li key={i}>{item}</li>
        ))}
      </ul>
      {loading && <p>Loading…</p>}
      {hasMore ? (
        <div ref={sentinelRef} data-testid="sentinel" />
      ) : (
        <p>End of results</p>
      )}
    </div>
  );
}
"})
