 * Hand-rolled IntersectionObserver mock for jsdom.
 *
 * Captures every created instance so tests can fire entries manually.
 * Install via `vi.stubGlobal("IntersectionObserver", MockIntersectionObserver)`
 * (or assign to globalThis) before rendering.
 */
export interface MockEntryInit {
  target: Element;
  isIntersecting?: boolean;
}

export class MockIntersectionObserver implements IntersectionObserver {
  static instances: MockIntersectionObserver[] = [];

  readonly root: Element | Document | null = null;
  readonly rootMargin: string;
  readonly thresholds: ReadonlyArray<number>;

  /** Elements currently observed; lets tests build entries automatically. */
  readonly observed = new Set<Element>();

  #callback: IntersectionObserverCallback;

  constructor(
    callback: IntersectionObserverCallback,
    options: IntersectionObserverInit = {},
  ) {
    this.#callback = callback;
    this.rootMargin = options.rootMargin ?? "0px";
    this.thresholds =
      options.threshold === undefined
        ? [0]
        : Array.isArray(options.threshold)
          ? options.threshold
          : [options.threshold];
    MockIntersectionObserver.instances.push(this);
  }

  observe(target: Element): void {
    this.observed.add(target);
  }

  unobserve(target: Element): void {
    this.observed.delete(target);
  }

  disconnect(): void {
    this.observed.clear();
  }

  takeRecords(): IntersectionObserverEntry[] {
    return [];
  }

  /** Fire the callback with synthetic entries. Defaults to all observed targets intersecting. */
  trigger(
    entries: MockEntryInit[] = [...this.observed].map((target) => ({ target })),
  ): void {
    this.#callback(
      entries.map(
        (e): IntersectionObserverEntry =>
          ({
            target: e.target,
            isIntersecting: e.isIntersecting ?? true,
            intersectionRatio: e.isIntersecting ?? true ? 1 : 0,
            time: Date.now(),
            boundingClientRect: e.target.getBoundingClientRect(),
            intersectionRect: e.target.getBoundingClientRect(),
            rootBounds: null,
          }) as unknown as IntersectionObserverEntry,
      ),
      this,
    );
  }

  /** Latest instance created (i.e. the one mounted by the last render). */
  static get latest(): MockIntersectionObserver {
    const instance = this.instances.at(-1);
    if (!instance) throw new Error("no IntersectionObserver instance created");
    return instance;
  }

  static reset(): void {
    this.instances = [];
  }
}
