import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { InfiniteList } from "../InfiniteList";
import {
  MockIntersectionObserver,
  type MockEntryInit,
} from "../test/intersection-observer-mock";

vi.stubGlobal("IntersectionObserver", MockIntersectionObserver);

afterEach(() => {
  cleanup();
  MockIntersectionObserver.reset();
  vi.restoreAllMocks();
});

/** Fire the given entries on the observer the component mounted. */
function fire(entries?: MockEntryInit[]) {
  MockIntersectionObserver.latest.trigger(entries);
}

describe("InfiniteList", () => {
  describe("intersect triggers exactly one loadMore while pending", () => {
    it("fires loadMore twice quickly but calls it once", async () => {
      const pending = new Promise<string[]>(() => {}); // never resolves
      const loadMore = vi.fn(() => pending);
      render(<InfiniteList loadMore={loadMore} />);

      expect(loadMore).not.toHaveBeenCalled();

      fire(); // sentinel enters viewport
      fire(); // second intersect while still pending

      expect(loadMore).toHaveBeenCalledTimes(1);
    });
  });

  describe("resolve appends items", () => {
    it("appends page contents when loadMore resolves", async () => {
      const loadMore = vi.fn(async () => ["a", "b", "c"]);
      render(<InfiniteList loadMore={loadMore} />);
      fire();
      await waitFor(() =>
        expect(screen.getByLabelText("items").children).toHaveLength(3),
      );
      expect(screen.getByText("a")).toBeInTheDocument();
      expect(screen.getByText("b")).toBeInTheDocument();
      expect(screen.getByText("c")).toBeInTheDocument();
    });

    it("keeps prior items and appends across multiple pages", async () => {
      const pages: string[][] = [["p1"], ["p2"], []];
      const loadMore = vi.fn(async () => pages.shift()!);
      render(<InfiniteList loadMore={loadMore} />);

      fire();
      await waitFor(() => expect(screen.getByText("p1")).toBeInTheDocument());
      fire();
      await waitFor(() => expect(screen.getByText("p2")).toBeInTheDocument());
      expect(loadMore).toHaveBeenCalledTimes(2);
    });
  });

  describe("exhaustion removes the sentinel and disconnects the observer", () => {
    it("shows End of results and disconnects", async () => {
      const disconnect = vi.spyOn(
        MockIntersectionObserver.prototype,
        "disconnect",
      );
      const loadMore = vi.fn(async () => ["only"]); // next call returns [] → exhausted
      const { queryByTestId } = render(<InfiniteList loadMore={loadMore} />);

      fire();
      await waitFor(() => expect(screen.getByText("only")).toBeInTheDocument());

      fire(); // triggers second page, which resolves empty
      await waitFor(() =>
        expect(screen.getByText("End of results")).toBeInTheDocument(),
      );

      expect(queryByTestId("sentinel")).toBeNull();
      expect(disconnect).toHaveBeenCalled();
    });
  });

  describe("retry path", () => {
    it("renders Retry on error and recovers after clicking it", async () => {
      let fail = true;
      const loadMore = vi.fn(async () => {
        if (fail) throw new Error("network down");
        return ["recovered"];
      });
      render(<InfiniteList loadMore={loadMore} />);

      // First intersect fails.
      fire();
      const alert = await screen.findByRole("alert");
      expect(alert).toHaveTextContent(/something went wrong/i);
      const retry = screen.getByRole("button", { name: /retry/i });

      // Make the loader succeed and click Retry — flow re-arms.
      fail = false;
      fireEvent.click(retry);

      await waitFor(() =>
        expect(screen.getByText("recovered")).toBeInTheDocument(),
      );
      expect(screen.queryByRole("alert")).toBeNull();
      expect(screen.getByTestId("sentinel")).toBeInTheDocument();
      // The observer was recreated for the re-armed effect cycle.
      expect(MockIntersectionObserver.instances.length).toBeGreaterThan(1);
      expect(loadMore).toHaveBeenCalledTimes(2);
    });
  });
});
"})
