export interface InfiniteListProps {
  /** Fetches the next page. Resolves with the new items (empty = exhausted); rejects on failure. */
  loadMore: () => Promise<string[]>;
}

/**
 * Infinite-scroll list.
 *
 * A sentinel div at the bottom is watched by an IntersectionObserver. When it
 * intersects, loadMore() runs — unless a load is already in flight or the list
 * is exhausted. An empty page marks exhaustion: the sentinel unmounts and
 * "End of results" shows. A rejected loadMore shows a Retry button; clicking
 * it bumps a retry counter that re-runs the effect, re-arming the observer.
 */
export function InfiniteList({ loadMore }: InfiniteListProps) {
  const [items, setItems] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<unknown>(null);
  const [hasMore, setHasMore] = useState(true);
  const [retryCount, setRetryCount] = useState(0);

  const sentinelRef = useRef<HTMLDivElement | null>(null);

  // Latest-state refs so the observer callback never sees stale values.
  const loadingRef = useRef(loading);
  const hasMoreRef = useRef(hasMore);
  loadingRef.current = loading;
  hasMoreRef.current = hasMore;

  useEffect(() => {
    if (!hasMore) return;
    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    let disposed = false;
    const observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        // Guard against duplicate triggers while a load is pending.
        if (loadingRef.current || !hasMoreRef.current) return;
        void run();
        return;
      }
    });
    observer.observe(sentinel);

    async function run() {
      setLoading(true);
      setError(null);
      try {
        const next = await loadMore();
        if (disposed) return;
        setItems((prev) => [...prev, ...next]);
        // Empty page = no more data.
        if (next.length === 0) setHasMore(false);
      } catch (err) {
        if (!disposed) setError(err);
      } finally {
        if (!disposed) setLoading(false);
      }
    }

    return () => {
      disposed = true;
      observer.disconnect();
    };
  }, [hasMore, retryCount, loadMore]);

  const retry = useCallback(() => {
    setError(null);
    setLoading(false);
    // Changing retryCount re-runs the effect above: a fresh observer is
    // created and the next intersect triggers loadMore again.
    setRetryCount((c) => c + 1);
  }, []);

  return (
    <div>
      <ul aria-label="items">
        {items.map((item, i) => (
          <li key={i}>{item}</li>
        ))}
      </ul>
      {error !== null && (
        <>
          <p role="alert">Something went wrong.</p>
          <button type="button" onClick={retry}>
            Retry
          </button>
        </>
      )}
      {loading && error === null && <p>Loading…</p>}
      {hasMore ? (
        <div ref={sentinelRef} data-testid="sentinel" />
      ) : (
        <p>End of results</p>
      )}
    </div>
  );
}
"})
